def _cursor_as_dict(conn):
    """Abre cursor compatible con pymssql y fallback pyodbc."""
    try:
        return conn.cursor(as_dict=True)
    except TypeError:
        return conn.cursor()


def _fetchall_dicts(cur):
    """Normaliza filas dict/tupla a dict sin depender del driver SQL."""
    rows = cur.fetchall() or []
    if not rows:
        return []
    if isinstance(rows[0], dict):
        return rows
    columns = [item[0] for item in (cur.description or [])]
    return [
        {columns[index]: row[index] for index in range(len(columns))}
        for row in rows
    ]


