def summarize_iscam_payments_output(output: str) -> dict[str, Any]:
    """Extrae evidencia segura del script de pagos sin publicar stdout crudo."""
    summary: dict[str, Any] = {}
    for raw_line in reversed((output or "").splitlines()):
        try:
            payload = json.loads(raw_line)
        except Exception:
            continue
        if not isinstance(payload, dict) or payload.get("event") != "resync":
            continue
        result = payload.get("result")
        if not isinstance(result, dict):
            return summary
        error = str(result.get("error") or "").strip()
        safe_error = ""
        error_type = ""
        if error:
            lower = error.lower()
            if lower == "config pos no resuelta":
                safe_error = "config_pos_no_resuelta"
            elif lower == "unidad no encontrada en canonico":
                safe_error = "unidad_no_encontrada"
            elif lower.startswith("extraccion:"):
                safe_error = "extraccion"
                parts = error.split(":", 2)
                if len(parts) >= 2:
                    error_type = parts[1].strip()[:80]
            else:
                safe_error = "resync_error"
                error_type = error.split(":", 1)[0][:80]
        summary = {
            key: result.get(key)
            for key in (
                "unidad", "sistema", "periodo", "pagos_extraidos",
                "pagos_insertados", "pagos_eliminados", "dry_run",
            )
            if key in result
        }
        if safe_error:
            summary["error_stage"] = safe_error
        if error_type:
            summary["error_type"] = error_type
        return summary
    return summary


